<template>
<div class="container mt-4 bg-white ">

  <div class="d-flex">
    <div class="ms-auto">
      <div class="btn-group mb-1">
        <button class="btn me-1 btn-sm" :class="filter_by ==='item'?'btn-primary':'btn-outline-primary'" @click="changeFilter('item')">Item List</button>
        <button class="btn me-1 btn-sm" :class="filter_by ==='category'?'btn-primary':'btn-outline-primary'" @click="changeFilter('category')">Category</button>
        <button class="btn  btn-sm" :class="filter_by ==='item_id'?'btn-primary':'btn-outline-primary'" @click="changeFilter('item_id')">Item ID</button>
      </div>
      <input type="number" class="form-control" placeholder="Enter Item id" v-model="item_id">
        <multiselect 
                    v-model="item"
                    :options= "itemsList"
                    label = "name"
                    placeholder="Select Item"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    ></multiselect>

                     <multiselect 
                    v-model="category"
                    :options= "categories"
                    label = "name"
                    placeholder="Select Category"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    ></multiselect>

    </div>
  </div>
  
  <div class="row m-2">
    
    <!-- LEFT -->
    <div class="col-md-5">
      <div class="card shadow-sm">
        <div class="card-header bg-primary text-white">
          Items
        </div>

        <div class="card-body p-2" style="max-height:70vh; overflow-y:auto;">
          <ul class="list-group">
            <li 
              v-for="row in items"
              :key="row.item.id"
              class="list-group-item list-group-item-action"
              style="cursor:pointer"
              @click="selectItem(row)"
            >
              <strong>#{{ row.item.id }}</strong> - {{ row.item.name }}
              <br>
              <small class="text-muted">{{ row.item.description }}</small>
            </li>
          </ul>
        </div>
      </div>
    </div>

    <!-- RIGHT -->
    <div class="col-md-7">
      <div class="card shadow-sm">
        <div class="card-header bg-dark text-white">
          Item Details
        </div>

        <div class="card-body">

          <div v-if="!selectedItem" class="text-muted text-center">
            Select an item
          </div>

          <div v-else>
            <h5>#{{ selectedItem.item.id }} - {{ selectedItem.item.name }}</h5>

            <hr>

            <div class="row">

              <div class="col-md-6">
                <div class="border p-3 mb-2">
                  Store Item IDs
                  <div class="mt-2">
                    <span 
                      v-for="id in selectedItem.store_item_ids" 
                      :key="id"
                      class="badge bg-danger me-1"
                    >
                      {{ id }}
                    </span>
                  </div>
                </div>
              </div>

              <div class="col-md-6">
                <div class="border p-3 mb-2">
                  Store IDs
                  <div class="mt-2">
                    <span 
                      v-for="id in selectedItem.store_ids" 
                      :key="id"
                      class="badge bg-primary me-1"
                    >
                      {{ id }}
                    </span>
                  </div>
                </div>
              </div>

              <div class="col-md-6">
                <div class="border p-3 mb-2">
                  LPO IDs
                  <div class="mt-2">
                    <span 
                      v-for="id in selectedItem.lpo_ids" 
                      :key="id"
                      class="badge bg-success me-1"
                    >
                      {{ id }}
                    </span>
                  </div>
                </div>
              </div>

              <div class="col-md-6">
                <div class="border p-3 mb-2">
                  GRN IDs
                  <div class="mt-2">
                    <span 
                      v-for="id in selectedItem.grn_ids" 
                      :key="id"
                      class="badge bg-warning text-dark me-1"
                    >
                      {{ id }}
                    </span>
                  </div>
                </div>
              </div>

              <div class="col-md-12">
                <div class="border p-3 mb-2">
                  GIN IDs
                  <div class="mt-2">
                    <span 
                      v-for="id in selectedItem.gin_ids" 
                      :key="id"
                      class="badge bg-dark me-1"
                    >
                      {{ id }}
                    </span>
                  </div>
                </div>
              </div>

            </div>

          </div>

        </div>
      </div>
    </div>

  </div>

</div>
</template>

<script setup>
import { ref, onMounted ,watch } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})

const items = ref([])
const selectedItem = ref(null)

const getItems = async (param) => {
  selectedItem.value = ''
  items.value = []
  const res = await axiosInstance.get(`/item-reports?${param}`)
  items.value = res.data
}

const itemsList = ref([])
const item = ref('')
const filter_by = ref('item')
const item_id = ref('')
const changeFilter = (filter)=>{
  filter_by.value = filter 
}
const getItemsList = async () => {
  const res = await axiosInstance.get('/item-list')
  itemsList.value = res.data
}

const selectItem = (row) => {
  selectedItem.value = row
}

const category = ref('')
const categories = ref([])
const getItemCategories = async () => {
  const res = await axiosInstance.get('/item-list-category')
  categories.value = res.data
}

    watch(item, (newVal) => {
    if (newVal) {
          getItems(`item_id=${newVal.id}`)
    }
});

    watch(item_id, (newVal) => {
    if (newVal) {
          getItems(`item_id=${newVal}`)
    }
});


    watch(category, (newVal) => {
    if (newVal) {
          getItems(`category_id=${newVal.id}`)
    }
});

onMounted(() => {
  getItemsList()
  getItemCategories()
})
</script>